import React from "react";
import Logo from "../img/RSALogo.png"

const Navbar = () => {
    return (
        <div>
            <nav className="p-5 bg-cyan-500">
                <div>
                    <span className="text-2xl font-mono">Rizal
                    <img className="h-10 inline" src={Logo} alt="" /></span>
                </div>
            </nav>
        </div>
    )

}


export default Navbar;
